import type { Container, Node, Root } from "postcss";
import type { PostcssResult } from "stylelint";
/** Where a span of a root's text opens and ends, relative to the root. */
export type Span = [number, number];
/**
 * Finds where a container's closing brace stands in its root's text, read off the file: the parser's end is the brace's, or that of a stray semicolon PostCSS files behind it in `raws.ownSemicolon`, where nothing but whitespace and semicolons stand between the two. A rule listed earlier may have written that raw, so its length tells nothing.
 * @param node - The container.
 * @returns The offset of the brace, or nothing where the parser's end cannot be trusted.
 */
export declare function braceOffset(node: Node): number | undefined;
/**
 * Finds where a container's closing brace stands counted from the container's start, where a warning about the brace is placed. Stylelint counts a problem's index over the file from the node's start, and the container's print, which a rule listed earlier may have rewritten, tells nothing of it: characters taken out in front of the brace put an index counted over the print on a line above it, under a disable comment covering that line. So the brace is found off the file, and the print, read through the brace with a stray `raws.ownSemicolon` cut off, is counted only where the file does not tell the brace.
 * @param node - The container.
 * @param print - The container's print, read through the brace.
 * @returns The index of the brace.
 */
export declare function braceIndex(node: Node, print: string): number;
/**
 * Finds where the character in front of a container's closing brace stands counted from the container's start, where a warning about the run in front of the brace is placed, as `braceIndex` finds the brace: the `\r` of a `\r\n` break there rather than its `\n`, read off the text the index counts in.
 * @param node - The container.
 * @param print - The container's print, read through the brace.
 * @returns The index.
 */
export declare function indexInFrontOfTheBrace(node: Node, print: string): number;
/**
 * Finds the span of the run in front of a node: from the end of the node in front of it, else from its block's opening brace or the root's start, to the node.
 * @param node - The node.
 * @param result - The Stylelint result, which holds the file's syntax.
 * @returns The span, or nothing where the file does not tell it.
 */
export declare function beforeSpan(node: Node, result: PostcssResult): Span | undefined;
/**
 * Finds the span of a node's head: from where it opens to its block's opening brace, or to its end where it holds no block.
 * @param node - The node.
 * @param result - The Stylelint result, which holds the file's syntax.
 * @returns The span, or nothing where the file does not tell it.
 */
export declare function headSpan(node: Node, result: PostcssResult): Span | undefined;
/**
 * Finds the span of the run in front of a block's closing brace: from the end of its last node, else from the opening brace.
 * @param node - The container.
 * @param result - The Stylelint result, which holds the file's syntax.
 * @returns The span, or nothing where the file does not tell it.
 */
export declare function afterSpan(node: Container, result: PostcssResult): Span | undefined;
/**
 * Finds the span of a stray semicolon behind a block's closing brace, with the run in front of it.
 * @param node - The container.
 * @returns The span, or nothing where the file does not tell it.
 */
export declare function ownSemicolonSpan(node: Node): Span | undefined;
/**
 * Finds the span of a root's tail: from the end of its last node to the end of its text.
 * @param root - The root.
 * @param result - The Stylelint result, which holds the file's syntax.
 * @returns The span.
 */
export declare function tailSpan(root: Root, result: PostcssResult): Span;
